query_text:
SELECT player.name, player.position, player.team
FROM player
WHERE player.age > 25;

SELECT player.name, player.draft_pick, player.college
FROM player
WHERE player.draft_pick >= 0;

SELECT team.team_name, team.ownership, team.championships
FROM team
WHERE team.championships > 0;

error:
Binder Error: Values list "team" does not have a column named "championships"

LINE 3: WHERE team.championships > 0;
              ^

query_text:
SELECT city.city_name, city.area, city.gdp
FROM city
WHERE city.area > 100;

SELECT owner.name, owner.age, owner.nationality
FROM owner
WHERE owner.age > 50;

SELECT player.name, player.birth_date, player.team, player.position
FROM player
WHERE player.age < 35;
